body.script:
        let player = { name: "", money: 1000, fraction: "Отсутствует", rank: "Нет", isOpg: false, adminLevel: 0 };
        const jobDetails = {
            miner: { text: "Добывать руду ⛏", pay: 150 },
            lumberjack: { text: "Валить лес 🪓", pay: 200 },
            woodcutter: { text: "Колоть дрова 🪵", pay: 180 },
            farmer: { text: "Собирать урожай 🚜", pay: 250 },
            trucker: { text: "Везти груз 🚚", pay: 500 }
        };

        function startGame() {
            const nameInput = document.getElementById('rp-name-input').value.trim();
            if (!/^[A-Z][a-z]+_[A-Z][a-z]+$/.test(nameInput)) {
                alert("Ошибка! Формат ника должен быть: Имя_Фамилия (Пример: Ivan_Ivanov)");
                return;
            }
            player.name = nameInput;
            document.getElementById('p-name').innerText = player.name;
            document.getElementById('auth-screen').style.display = 'none';
            document.getElementById('game-screen').style.display = 'block';
            updateUI();
        }

        function addMsg(sender, text, color = "#ffffff") {
            const box = document.getElementById('chat-box');
            box.innerHTML += `
${sender} ${text}`;
            box.scrollTop = box.scrollHeight;
        }

        function sendAction() {
            const input = document.getElementById('chat-input');
            const str = input.value.trim();
            if (!str) return;

            if (str.startsWith('/')) {
                const args = str.split(' ');
                const cmd = args[0].toLowerCase();

                if (cmd === '/help') {
                    addMsg("[Помощь]", "Команды: /pass, /report [текст], /ah, /setadmin [0-4], /money [сумма], /clear", "#f1c40f");
                } else if (cmd === '/pass') {
                    addMsg("[Паспорт]", `Гражданин: ${player.name} | Баланс: ${player.money}$ | Фракция: ${player.fraction}`, "#3498db");
                } else if (cmd === '/report') {
                    addMsg("[Репорт]", `Отправлено: "${args.slice(1).join(' ')}"`, "#f39c12");
                    setTimeout(() => addMsg("[Поддержка]", "Спешу на помощь! Приятной игры.", "#e67e22"), 1200);
                } else if (cmd === '/setadmin') {
                    let lvl = parseInt(args[1]);
                    if (!isNaN(lvl) && lvl >= 0 && lvl <= 4) {
                        player.adminLevel = lvl;
                        document.getElementById('p-admin').innerText = lvl > 0 ? `Админ (${lvl} лвл)` : "Игрок";
                        addMsg("[Админка]", `Установлен уровень: ${lvl}`, "#e74c3c");
                    }
                } else if (cmd === '/ah') {
                    if (player.adminLevel > 0) addMsg("[Админ]", "Доступно: /money [сумма], /clear", "#e74c3c");
                    else addMsg("[Ошибка]", "Вы не админ!", "#c0392b");
                } else if (cmd === '/money') {
                    let count = parseInt(args[1]);
                    if (player.adminLevel >= 2 && !isNaN(count)) { player.money += count; updateUI(); addMsg("[Админ]", `Выдано ${count}$`, "#e74c3c"); }
                } else if (cmd === '/clear') {
                    if (player.adminLevel >= 1) document.getElementById('chat-box').innerHTML = "";
                } else {
                    addMsg("[Ошибка]", "Неизвестная команда. Введите /help", "#c0392b");
                }
            } else {addMsg([Общий] ${player.name}:, str, player.isOpg ? "#c0392b" : "#3498db");}input.value = "";}function updateUI() {document.getElementById('p-money').innerText = player.money + " $";document.getElementById('p-frac').innerText = player.fraction;document.getElementById('p-rank').innerText = player.rank;}function switchTab(id) {document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));document.getElementById(id).classList.add('active');if(id === 'profile') document.getElementById('b-prof').classList.add('active');if(id === 'jobs') document.getElementById('b-jobs').classList.add('active');if(id === 'fractions') document.getElementById('b-frac').classList.add('active');}function updateJobInfo() {document.getElementById('work-btn').innerText = jobDetails[document.getElementById('job-select').value].text;}function doWork() {player.money += jobDetails[document.getElementById('job-select').value].pay;updateUI();}function joinFraction(type) {if (type === 'gov') { player.fraction = document.getElementById('gov-select').value; player.rank = "Рядовой (1)"; player.isOpg = false; }else { player.fraction = document.getElementById('opg-select').value; player.rank = "Браток (1)"; player.isOpg = true; }updateUI();addMsg("[Фракция]", Вы вступили в: ${player.fraction}, "#9b59b6");}function leaveFraction() {if (player.fraction === "Отсутствует") return;addMsg("[Фракция]", Вы уволились из ${player.fraction}, "#7f8c8d");player.fraction = "Отсутствует"; player.rank = "Нет"; player.isOpg = false;updateUI();}setInterval(() => { if (player.fraction !== "Отсутствует") { player.money += player.isOpg ? 400 : 600; updateUI(); } }, 10000);updateJobInfo();updateUI();
